<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{Auth,DB,Hash};
use Illuminate\Validation\ValidationException;
use App\Models\{User,Item,Supplier,Warehouse,PurchaseOrder,PurchaseOrderItem,GoodsReceipt,GoodsReceiptItem,GoodsReceiptLot,QcInspection,QcInspectionSample,QcInspectionResult,StockMovement,SupplierInvoice,SupplierInvoiceItem,AuditLog};
class ErpController extends Controller {
private function role(array $roles):void {abort_unless(in_array(Auth::user()->role,$roles,true),403,'Insufficient role');}
private function audit(string $action,$entity):void {AuditLog::create(['user_id'=>Auth::id(),'action'=>$action,'entity'=>class_basename($entity),'entity_id'=>$entity->id]);}
public function me(){return response()->json(Auth::user());}
public function login(Request $r){$v=$r->validate(['email'=>'required|email','password'=>'required']);if(!Auth::attempt($v))throw ValidationException::withMessages(['email'=>'Invalid credentials']);$r->session()->regenerate();return $this->me();}
public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return ['ok'=>true];}
public function overview(){return ['items'=>Item::with(['qcParameters','samplingRules'])->get(),'suppliers'=>Supplier::all(),'warehouses'=>Warehouse::all(),'purchase_orders'=>PurchaseOrder::with('lines')->latest()->get(),'goods_receipts'=>GoodsReceipt::with('lines.lots')->latest()->get(),'lots'=>GoodsReceiptLot::with('inspections.samples.results')->latest()->get(),'inspections'=>QcInspection::with('samples.results')->latest()->get(),'stock_movements'=>StockMovement::latest()->get(),'invoices'=>SupplierInvoice::with('lines')->latest()->get(),'audit'=>AuditLog::latest()->limit(100)->get()];}
public function item(Request $r){$this->role(['buyer','manager']);$v=$r->validate(['item_code'=>'required|string|max:100|unique:items','name'=>'required|string','category'=>'required|string','uom'=>'required|string','qc_required'=>'required|boolean','min_lot_size'=>'required|integer|min:1','max_lot_size'=>'nullable|integer|gte:min_lot_size','parameters'=>'required_if:qc_required,1|array','parameters.*.parameter_name'=>'required|string','parameters.*.min_value'=>'required|numeric','parameters.*.max_value'=>'required|numeric','parameters.*.unit'=>'required|string','rules'=>'required_if:qc_required,1|array','rules.*.min_quantity'=>'required|integer|min:1','rules.*.max_quantity'=>'nullable|integer','rules.*.sample_count'=>'required|integer|min:1']);
$rules=$v['rules']??[];usort($rules,fn($a,$b)=>$a['min_quantity']<=>$b['min_quantity']);$end=0;foreach($rules as $i=>$rule){if($rule['min_quantity']<=$end || ($i && $rules[$i-1]['max_quantity']===null))throw ValidationException::withMessages(['rules'=>'Overlapping or unreachable sampling ranges']);if($rule['max_quantity']!==null && $rule['max_quantity']<$rule['min_quantity'])throw ValidationException::withMessages(['rules'=>'Invalid maximum quantity']);$end=$rule['max_quantity']??PHP_INT_MAX;}
foreach($v['parameters']??[] as $p)if($p['min_value']>$p['max_value'])throw ValidationException::withMessages(['parameters'=>'Parameter minimum exceeds maximum']);
return DB::transaction(function()use($v,$rules){$item=Item::create(collect($v)->except(['parameters','rules'])->all());foreach($v['parameters']??[] as $p)$item->qcParameters()->create($p+['is_required'=>true]);foreach($rules as $rule)$item->samplingRules()->create($rule);$this->audit('create',$item);return $item->load(['qcParameters','samplingRules']);});}
public function samples(Item $item,Request $r){$q=$r->validate(['lot_quantity'=>'required|integer|min:1'])['lot_quantity'];return ['item_code'=>$item->item_code,'lot_quantity'=>$q,'required_samples'=>$this->sampleCount($item,$q)];}
private function sampleCount(Item $item,int $qty):int {if($qty<$item->min_lot_size || ($item->max_lot_size!==null && $qty>$item->max_lot_size))throw ValidationException::withMessages(['quantity'=>'Outside item lot size limits']);if(!$item->qc_required)return 0;$rules=$item->samplingRules()->where('min_quantity','<=',$qty)->where(fn($q)=>$q->where('max_quantity','>=',$qty)->orWhereNull('max_quantity'))->get();if($rules->count()!==1)throw ValidationException::withMessages(['rules'=>'Expected exactly one matching QC sampling rule']);return min($qty,$rules->first()->sample_count);}
public function supplier(Request $r){$this->role(['buyer','manager']);$v=$r->validate(['name'=>'required|string','gst_number'=>'nullable|string','email'=>'nullable|email']);$s=Supplier::create($v);$this->audit('create',$s);return $s;}
public function warehouse(Request $r){$this->role(['buyer','manager']);$v=$r->validate(['name'=>'required|string','code'=>'required|string|unique:warehouses']);$s=Warehouse::create($v);$this->audit('create',$s);return $s;}
public function po(Request $r){$this->role(['buyer','manager']);$v=$r->validate(['supplier_id'=>'required|exists:suppliers,id','warehouse_id'=>'required|exists:warehouses,id','order_date'=>'required|date','expected_date'=>'nullable|date|after_or_equal:order_date','lines'=>'required|array|min:1','lines.*.item_id'=>'required|exists:items,id','lines.*.quantity'=>'required|integer|min:1','lines.*.unit_price'=>'required|numeric|min:0','lines.*.tax_rate'=>'required|numeric|between:0,100']);return DB::transaction(function()use($v){$po=PurchaseOrder::create(['po_number'=>'PO-'.strtoupper((string)\Illuminate\Support\Str::ulid()),'supplier_id'=>$v['supplier_id'],'warehouse_id'=>$v['warehouse_id'],'created_by'=>Auth::id(),'order_date'=>$v['order_date'],'expected_date'=>($v['expected_date']?:null),'status'=>'draft','total'=>0]);$total=0;foreach($v['lines'] as $line){$item=Item::findOrFail($line['item_id']);$sum=round($line['quantity']*$line['unit_price']*(1+$line['tax_rate']/100),2);$po->lines()->create($line+['uom'=>$item->uom,'line_total'=>$sum]);$total+=$sum;}$po->update(['total'=>round($total,2)]);$this->audit('create',$po);return $po->load('lines');});}
public function poAction(PurchaseOrder $po,string $action){$this->role($action==='approve'?['manager']:['buyer','manager']);return DB::transaction(function()use($po,$action){$po=PurchaseOrder::whereKey($po->id)->lockForUpdate()->firstOrFail();if($action==='submit' && $po->status==='draft')$po->update(['status'=>'submitted']);elseif($action==='approve' && $po->status==='submitted')$po->update(['status'=>'approved','approved_by'=>Auth::id()]);else throw ValidationException::withMessages(['status'=>'Invalid PO status transition']);$this->audit($action,$po);return $po;});}
public function grn(Request $r){$this->role(['buyer','manager']);$v=$r->validate(['purchase_order_id'=>'required|exists:purchase_orders,id','received_date'=>'required|date','lines'=>'required|array|min:1','lines.*.purchase_order_item_id'=>'required|exists:purchase_order_items,id','lines.*.lots'=>'required|array|min:1','lines.*.lots.*.lot_number'=>'required|string','lines.*.lots.*.quantity'=>'required|integer|min:1','lines.*.lots.*.manufactured_at'=>'nullable|date','lines.*.lots.*.expires_at'=>'nullable|date']);return DB::transaction(function()use($v){$po=PurchaseOrder::whereKey($v['purchase_order_id'])->lockForUpdate()->firstOrFail();$po->load('lines');if(!in_array($po->status,['approved','partially_received']))throw ValidationException::withMessages(['po'=>'PO must be approved']);$grn=GoodsReceipt::create(['grn_number'=>'GRN-'.strtoupper((string)\Illuminate\Support\Str::ulid()),'purchase_order_id'=>$po->id,'created_by'=>Auth::id(),'received_date'=>$v['received_date']]);$seen=[];foreach($v['lines'] as $line){$lineId=$line['purchase_order_item_id'];if(isset($seen[$lineId]))throw ValidationException::withMessages(['lines'=>'Duplicate PO line']);$seen[$lineId]=true;$poLine=PurchaseOrderItem::whereKey($lineId)->where('purchase_order_id',$po->id)->firstOrFail();$qty=array_sum(array_column($line['lots'],'quantity'));$prior=GoodsReceiptItem::where('purchase_order_item_id',$lineId)->sum('quantity');if($qty+$prior>$poLine->quantity)throw ValidationException::withMessages(['quantity'=>'GRN exceeds outstanding PO quantity']);$grnLine=$grn->lines()->create(['purchase_order_item_id'=>$lineId,'quantity'=>$qty]);$item=Item::findOrFail($poLine->item_id);foreach($line['lots'] as $lot){if($lot['quantity']<$item->min_lot_size || ($item->max_lot_size!==null && $lot['quantity']>$item->max_lot_size))throw ValidationException::withMessages(['lot'=>'Lot quantity outside item limits']);$lot['manufactured_at']=$lot['manufactured_at']?:null;$lot['expires_at']=$lot['expires_at']?:null;$l=$grnLine->lots()->create($lot+['qc_status'=>$item->qc_required?'hold':'passed']);StockMovement::create(['goods_receipt_lot_id'=>$l->id,'item_id'=>$item->id,'warehouse_id'=>$po->warehouse_id,'from_bucket'=>null,'to_bucket'=>$item->qc_required?'hold':'available','quantity'=>$l->quantity,'reference'=>'RECEIPT-'.$l->id]);}}
$complete=$po->lines->every(fn($l)=>(int)GoodsReceiptItem::where('purchase_order_item_id',$l->id)->sum('quantity')===(int)$l->quantity);$po->update(['status'=>$complete?'fully_received':'partially_received']);$this->audit('create',$grn);return $grn->load('lines.lots');});}
public function startInspection(GoodsReceiptLot $lot){$this->role(['inspector','qc_manager']);return DB::transaction(function()use($lot){$lot=GoodsReceiptLot::whereKey($lot->id)->lockForUpdate()->firstOrFail();if($lot->qc_status!=='hold')throw ValidationException::withMessages(['lot'=>'Only held lots can be inspected']);if(QcInspection::where('goods_receipt_lot_id',$lot->id)->whereIn('status',['draft','submitted','passed'])->exists())throw ValidationException::withMessages(['inspection'=>'An active or passed inspection already exists']);$line=GoodsReceiptItem::findOrFail($lot->goods_receipt_item_id);$poLine=PurchaseOrderItem::findOrFail($line->purchase_order_item_id);$item=Item::with('qcParameters')->findOrFail($poLine->item_id);$count=$this->sampleCount($item,$lot->quantity);if($count===0)throw ValidationException::withMessages(['qc'=>'QC is not required']);$rule=$item->samplingRules()->where('min_quantity','<=',$lot->quantity)->where(fn($q)=>$q->where('max_quantity','>=',$lot->quantity)->orWhereNull('max_quantity'))->firstOrFail();$inspection=QcInspection::create(['goods_receipt_lot_id'=>$lot->id,'inspector_id'=>Auth::id(),'required_samples'=>$count,'parameters_snapshot'=>$item->qcParameters->map(fn($p)=>['name'=>$p->parameter_name,'min'=>(float)$p->min_value,'max'=>(float)$p->max_value,'unit'=>$p->unit,'required'=>(bool)$p->is_required])->all(),'sampling_rule_snapshot'=>['min_quantity'=>$rule->min_quantity,'max_quantity'=>$rule->max_quantity,'sample_count'=>$rule->sample_count],'status'=>'draft']);for($i=1;$i<=$count;$i++)$inspection->samples()->create(['sample_number'=>$i]);$this->audit('start',$inspection);return $inspection->load('samples.results');});}
public function saveMeasurements(Request $r,QcInspection $inspection){$this->role(['inspector','qc_manager']);$v=$r->validate(['readings'=>'required|array','readings.*.sample_number'=>'required|integer|min:1','readings.*.values'=>'required|array']);return DB::transaction(function()use($v,$inspection){$inspection=QcInspection::whereKey($inspection->id)->lockForUpdate()->firstOrFail();if($inspection->status!=='draft')throw ValidationException::withMessages(['inspection'=>'Inspection is not editable']);$params=collect($inspection->parameters_snapshot);foreach($v['readings'] as $reading){$sample=$inspection->samples()->where('sample_number',$reading['sample_number'])->firstOrFail();foreach($reading['values'] as $name=>$value){$param=$params->firstWhere('name',$name);if(!$param)throw ValidationException::withMessages(['parameter'=>'Unknown parameter: '.$name]);if(!is_numeric($value))throw ValidationException::withMessages(['value'=>'Measurements must be numeric']);$passed=(float)$value>=$param['min'] && (float)$value<=$param['max'];$sample->results()->updateOrCreate(['parameter_name'=>$name],['measured_value'=>$value,'passed'=>$passed]);}}$this->audit('measure',$inspection);return $inspection->load('samples.results');});}
public function submitInspection(QcInspection $inspection){$this->role(['inspector','qc_manager']);return DB::transaction(function()use($inspection){$inspection=QcInspection::whereKey($inspection->id)->lockForUpdate()->firstOrFail();if($inspection->status!=='draft')throw ValidationException::withMessages(['inspection'=>'Not a draft']);$inspection->load('samples.results');$required=collect($inspection->parameters_snapshot)->where('required',true)->pluck('name')->all();if($inspection->samples->count()!==$inspection->required_samples)throw ValidationException::withMessages(['samples'=>'Sample count mismatch']);foreach($inspection->samples as $sample)foreach($required as $name)if(!$sample->results->contains('parameter_name',$name))throw ValidationException::withMessages(['measurements'=>'Missing required reading for sample '.$sample->sample_number.': '.$name]);$inspection->update(['status'=>'submitted','submitted_at'=>now()]);$this->audit('submit',$inspection);return $inspection;});}
public function approveInspection(Request $r,QcInspection $inspection){$this->role(['qc_manager']);$v=$r->validate(['reason'=>'nullable|string']);return DB::transaction(function()use($inspection,$v){$inspection=QcInspection::whereKey($inspection->id)->lockForUpdate()->firstOrFail();if($inspection->status!=='submitted')throw ValidationException::withMessages(['inspection'=>'Inspection not submitted']);if($inspection->inspector_id===Auth::id())throw ValidationException::withMessages(['approver'=>'Inspector cannot approve their own inspection']);$lot=GoodsReceiptLot::whereKey($inspection->goods_receipt_lot_id)->lockForUpdate()->firstOrFail();if($lot->qc_status!=='hold')throw ValidationException::withMessages(['lot'=>'Lot is not on hold']);$failed=QcInspectionResult::whereIn('qc_inspection_sample_id',$inspection->samples()->pluck('id'))->where('passed',false)->exists();$line=GoodsReceiptItem::findOrFail($lot->goods_receipt_item_id);$poLine=PurchaseOrderItem::findOrFail($line->purchase_order_item_id);$grn=GoodsReceipt::findOrFail($line->goods_receipt_id);$po=PurchaseOrder::findOrFail($grn->purchase_order_id);$inspection->update(['status'=>$failed?'failed':'passed','approver_id'=>Auth::id(),'reason'=>$failed?($v['reason']??'Out-of-range measurement'):null,'approved_at'=>now()]);$lot->update(['qc_status'=>$failed?'rejected':'passed']);StockMovement::create(['goods_receipt_lot_id'=>$lot->id,'item_id'=>$poLine->item_id,'warehouse_id'=>$po->warehouse_id,'from_bucket'=>'hold','to_bucket'=>$failed?'rejected':'available','quantity'=>$lot->quantity,'reference'=>'QC-'.$inspection->id]);$this->audit('approve',$inspection);return $inspection;});}
public function invoice(Request $r){$this->role(['accounts','manager']);$v=$r->validate(['invoice_number'=>'required|string','purchase_order_id'=>'required|exists:purchase_orders,id','invoice_date'=>'required|date','lines'=>'required|array|min:1','lines.*.goods_receipt_lot_id'=>'required|exists:goods_receipt_lots,id','lines.*.quantity'=>'required|integer|min:1']);return DB::transaction(function()use($v){$po=PurchaseOrder::whereKey($v['purchase_order_id'])->lockForUpdate()->firstOrFail();$invoice=SupplierInvoice::create(['invoice_number'=>$v['invoice_number'],'supplier_id'=>$po->supplier_id,'purchase_order_id'=>$po->id,'created_by'=>Auth::id(),'invoice_date'=>$v['invoice_date'],'total'=>0,'status'=>'draft']);$total=0;$seen=[];foreach($v['lines'] as $line){$lot=GoodsReceiptLot::whereKey($line['goods_receipt_lot_id'])->lockForUpdate()->firstOrFail();if(isset($seen[$lot->id]))throw ValidationException::withMessages(['lines'=>'Duplicate lot']);$seen[$lot->id]=true;if($lot->qc_status!=='passed')throw ValidationException::withMessages(['lot'=>'Only accepted lots can be invoiced']);$grnLine=GoodsReceiptItem::findOrFail($lot->goods_receipt_item_id);$grn=GoodsReceipt::findOrFail($grnLine->goods_receipt_id);if($grn->purchase_order_id!==$po->id)throw ValidationException::withMessages(['lot'=>'Lot does not belong to PO']);$poLine=PurchaseOrderItem::findOrFail($grnLine->purchase_order_item_id);$already=SupplierInvoiceItem::where('goods_receipt_lot_id',$lot->id)->sum('quantity');if($already+$line['quantity']>$lot->quantity)throw ValidationException::withMessages(['quantity'=>'Invoice exceeds unbilled accepted lot quantity']);$sum=round($line['quantity']*$poLine->unit_price*(1+$poLine->tax_rate/100),2);$invoice->lines()->create(['goods_receipt_lot_id'=>$lot->id,'quantity'=>$line['quantity'],'unit_price'=>$poLine->unit_price,'tax_rate'=>$poLine->tax_rate,'line_total'=>$sum]);$total+=$sum;}$invoice->update(['total'=>round($total,2)]);$this->audit('create',$invoice);return $invoice->load('lines');});}
}
